import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r', 'parent')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r; self.parent = None

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l); n.l.parent = n
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r); n.r.parent = n
        i += 1
    return root

def find_node(root, v):
    if not root: return None
    q = deque([root])
    while q:
        n = q.popleft()
        if n.v == v: return n
        if n.l: q.append(n.l)
        if n.r: q.append(n.r)
    return None

def lca_best(root, p, q):
    pn, qn = find_node(root, p), find_node(root, q)
    s = set()
    cur = pn
    while cur:
        s.add(cur); cur = cur.parent
    cur = qn
    while cur not in s:
        cur = cur.parent
    return cur

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    arr = data[1:1 + n]
    p = int(data[1 + n]); q = int(data[2 + n])
    root = build(arr)
    r = lca_best(root, p, q)
    print(r.v if r else 'n')
